ue a suscipit luctus neque purus ipsum neque dolor primis libero at tempus blandit posuere magna sagittis congue augue magna risus mauris and volutpat and egestas\\\"\",\"name_item\":\"- AJ\",\"_id\":\"6a6b936\"}]},\"elements\":[],\"widgetType\":\"bdevs-testimonials-section\"}],\"isInner\":false}],\"isInner\":false},{\"id\":\"d07f699\",\"elType\":\"section\",\"settings\":{\"layout\":\"full_width\",\"gap\":\"no\"},\"elements\":[{\"id\":\"467963b\",\"elType\":\"column\",\"settings\":{\"_column_size\":100,\"_inline_size\":null},\"elements\":[{\"id\":\"8be66bc\",\"elType\":\"widget\",\"settings\":{\"id_section\":\"promo-4\",\"title\":\"La Notte\",\"tabs\":[{\"tab_title\":\"Slide #1\",\"tab_content\":\"I am item content. Click edit button to change this text.\",\"_id\":\"ff9308b\",\"link_item\":\"\",\"text_item\":\"\"}],\"bg_left\":{\"url\":\"https:\\/\\/shtheme.com\\/demosd\\/lanotte\\/wp-content\\/uploads\\/2023\\/05\\/pb_4-1.jpg\",\"id\":317,\"size\":\"\",\"alt\":\"\",\"source\":\"library\"},\"heading1\":\"A Brush Of Perfection\",\"title1\":\"Follow & Share\",\"link1\":\"https:\\/\\/www.instagram.com\\/\",\"text1\":\"@la_notte_nail\",\"link_button1\":\"https:\\/\\/shtheme.com\\/demosd\\/lanotte\\/?page_id=88\",\"text_button1\":\"View Our Gallery\",\"heading2\":\"Make it happen\",\"title2\":\"Gift <span> Cards <\\/span>\",\"link_button2\":\"https:\\/\\/shtheme.com\\/demosd\\/lanotte\\/?page_id=92\",\"text_btton2\":\"Find out more\",\"bg_right\":{\"url\":\"https:\\/\\/shtheme.com\\/demosd\\/lanotte\\/wp-content\\/uploads\\/2023\\/05\\/pb_4-2.jpg\",\"id\":318,\"size\":\"\",\"alt\":\"\",\"source\":\"library\"},\"text_button2\":\"Find out more\"},\"elements\":[],\"widgetType\":\"bdevs-promo-section\"}],\"isInner\":false}],\"isInner\":false},{\"id\":\"fbb1771\",\"elType\":\"section\",\"settings\":{\"layout\":\"full_width\",\"gap\":\"no\"},\"elements\":[{\"id\":\"552d413\",\"elType\":\"column\",\"settings\":{\"_column_size\":100,\"_inline_size\":null},\"elements\":[{\"id\":\